int DoCatchFromLoader_9050()
{
    int &Task=iCatchFromLoader9050Task;
    switch(Task)
    {
        case 1:                                                                 //Step 1: MTrayX 移到 Loader X 位置
            if(MTrayXCanSafeMove()==false)
            {
                MOT[MTrayX].PCIL132_StopMotor();
                Task=1;
                return 3;
            }
            if(TrayXMoveCheckEnc(Prod.iXTrayLoad)==1)
            {
                if(IniConfig.bEnable_SECS_GEM==true)
                    EventReport(SECS_EVENT.TrayTestFinish);
                if(MOT[MTrayX].fHasTray)
                {
                    Task=10;
                }
                else
                Task=10;
            }
            break;
        case 10:
            if(Cylinder[C_LoaderEdgeClip].Pop() &&
               Cylinder[C_LoaderEdgePush].Pop())
            {
                if(MOT[MLoaderZ].MotorMove(W906_TrayZ9050(0, 1, iLoaderLayerCount_9050))==1)   //AI(W906-TRAYZ-PITCH) 20261006: was Prod.TrayZ_Up[iLoaderLayerCount_9050]
                    Task=20;
            }
            break;
        case 20:
            Cylinder[C_TrayZ_Selector].On();
            MOT[MLoaderZ].ClearTray(__FUNC__);
            iLoaderLayerCount_9050++;
            Task=30;
            break;
        case 30:
            if(Cylinder[C_LoaderEdgeClip].Pop() &&
               Cylinder[C_LoaderEdgePush].Pop() &&
               Cylinder[C_TrayZ_Selector].Push() &&
               Cylinder[C_MobileTrayTableSelect].Push())
            {
                if(MOT[MLoaderZ].MotorMove(W906_TrayZ9050(0, 1, iLoaderLayerCount_9050) + W906_TrayZ9050Lift(0))==1)   //AI(W906-TRAYZ-PITCH) 20261006: was Prod.TrayZ_Up[..] + Prod.iCatchExtraLift_9050 (hand-over = Up + taught lift, EastSun「對那額外抬升也要校正」)
                {
                    Task=40;
                }
            }
            break;
        case 40:
            Cylinder[C_MobileTrayTableSelect].Off();
            MOT[MTrayX].fHasTray = true;
            //AI(W906-F9050-FIX1) 20261005: 偏離 910（910 acatchtray.cpp:2492-2494 是 MMTrayZ，作者裁決）—— Frank 本人 1005「目前的應該是MMTrayY才對，
            //  MMTrayZ是馬達動作，在程式裡面資訊流判斷都是以Y為主」：DoLoadNewICTray_9050 case 300 把盤記在 MMTrayY（asendic_Loader.cpp），
            //  這裡清 MMTrayZ 的話 MMTrayY 永遠「有盤」，DoCatchTray 會一直回 Loader 空夾、DoLoad_9050 不補盤（Frank01 1005 D 批審查缺陷 (f)）。
            //  910 原文：MOT[MTrayX].iIsCoverTray = MOT[MMTrayZ].iIsCoverTray; MOT[MTrayX].sTrayID = MOT[MMTrayZ].sTrayID; MOT[MMTrayZ].ClearTray(__FUNC__);
            MOT[MTrayX].iIsCoverTray = MOT[MMTrayY].iIsCoverTray;
            MOT[MTrayX].sTrayID      = MOT[MMTrayY].sTrayID;
            MOT[MMTrayY].ClearTray(__FUNC__);
            Task=50;
            break;
        case 50:
            if(Cylinder[C_MobileTrayTableSelect].Pop())
            {
                if(MOT[MLoaderZ].MotorMove(W906_TrayZ9050(0, 0, iLoaderLayerCount_9050))==1)   //AI(W906-TRAYZ-PITCH) 20261006: was Prod.TrayZ_Down[iLoaderLayerCount_9050]
                {
                    Task=60;
                }
            }
            break;
        case 60:                                                                
            {
                int xTarget = (IniConfig.bP56TrayArmWaitAtColorTrack ||
                               (INSTALL_OCR!=eocrUninstal && CosFunction.bTrayOCR))
                              ? Prod.iXTrayColor
                              : Prod.iXTrayEmpty;
                if(TrayArmMotorMove(xTarget))
                {
                    MOT[MInArmX].fCanMove=true;
                    MOT[MInArmY].fCanMove=true;
                    bCatchTrayFinishAction=false;
                    Task=1;
                    return 1;
                }
            }
            break;
    }
    return 0;
}

